// Perfil de la cuenta. Es lo único que se toca para cambiar a quién buscar.
const CUENTA = 'DESPA TRANSPORTES';

// Dónde vive cada cosa. En el mismo Docker que n8n el scraper se llama por su
// nombre de contenedor; Browth corre afuera, en tu máquina, y desde adentro de
// un contenedor eso es host.docker.internal.
const SCRAPER_URL = 'http://browth-scraper:8080';
const BROWTH_URL = 'http://host.docker.internal:3000';

const RUBROS = [
  'metalúrgica',
  'fábrica de plásticos',
  'fábrica de muebles',
  'imprenta industrial',
  'distribuidora mayorista',
  'importadora',
  'ferretería industrial',
  'corralón',
  'equipamiento gastronómico',
  'tienda de bebés',
  'juguetería mayorista',
  'decoración del hogar',
  'distribuidora textil',
  'mayorista de telas',
];

const ZONAS = [
  'Villa Crespo, Buenos Aires',
  'Barracas, Buenos Aires',
  'Parque Patricios, Buenos Aires',
  'Flores, Buenos Aires',
  'Villa Devoto, Buenos Aires',
  'Avellaneda, Buenos Aires',
  'San Martín, Buenos Aires',
  'Tres de Febrero, Buenos Aires',
];

// Cuántas búsquedas por semana. Cada una tarda unos minutos, así que conviene
// ir de a poco: el flujo rota solo y en unas semanas cubre todo el mapa.
const POR_SEMANA = 12;
const PROFUNDIDAD = 2; // cuántas pantallas de resultados baja en cada búsqueda

// Todas las combinaciones rubro × zona, en orden fijo.
const todas = [];
for (const r of RUBROS) for (const z of ZONAS) todas.push(`${r} en ${z}`);

// Rotación semanal: la semana 1 toma las primeras 12, la 2 las 12 siguientes,
// y cuando da la vuelta vuelve a empezar. Así no repite lo mismo cada lunes.
const inicioDeAno = new Date(new Date().getFullYear(), 0, 1);
const semana = Math.floor((Date.now() - inicioDeAno) / (7 * 24 * 60 * 60 * 1000));
const vueltas = Math.ceil(todas.length / POR_SEMANA);
const desde = (semana % vueltas) * POR_SEMANA;
const keywords = todas.slice(desde, desde + POR_SEMANA);

return [{
  json: {
    cuenta: CUENTA,
    scraperUrl: SCRAPER_URL,
    browthUrl: BROWTH_URL,
    keywords,
    profundidad: PROFUNDIDAD,
    tanda: `${desde + 1}-${desde + keywords.length} de ${todas.length}`,
  },
}];

// El CSV del scraper trae 36 columnas; a Browth le mandamos las que usa.
// El resto (horarios, reseñas, fotos) no aporta a una lista de contacto.
function parseCsv(t) {
  t = String(t || '').replace(/^\uFEFF/, '');
  const filas = [];
  let fila = [], celda = '', comillas = false;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (comillas) {
      if (c === '"') { if (t[i + 1] === '"') { celda += '"'; i++; } else comillas = false; }
      else celda += c;
    } else if (c === '"') comillas = true;
    else if (c === ',') { fila.push(celda); celda = ''; }
    else if (c === '\n') { fila.push(celda); filas.push(fila); fila = []; celda = ''; }
    else if (c !== '\r') celda += c;
  }
  if (celda || fila.length) { fila.push(celda); filas.push(fila); }
  return filas;
}

const crudo = $input.first().json.data ?? $input.first().json.body ?? '';
const filas = parseCsv(crudo);
if (filas.length < 2) throw new Error('El CSV vino vacío: revisá el job en el scraper.');

const cab = filas[0];
const col = (n) => cab.indexOf(n);
const I = {
  title: col('title'), category: col('category'), address: col('address'),
  completa: col('complete_address'), website: col('website'), phone: col('phone'),
  emails: col('emails'), link: col('link'),
  rating: col('review_rating'), resenas: col('review_count'), estado: col('status'),
};

const cuenta = $('Perfil y búsquedas de la semana').first().json.cuenta;

return filas.slice(1)
  .filter((f) => f.length > 3 && f[I.title])
  // Los locales cerrados no sirven para prospectar.
  .filter((f) => !/permanently_closed|closed_permanently/i.test(f[I.estado] || ''))
  .map((f) => ({
    json: {
      cuenta,
      title: f[I.title],
      category: f[I.category] || '',
      address: f[I.address] || '',
      complete_address: f[I.completa] || '',
      website: f[I.website] || '',
      phone: f[I.phone] || '',
      emails: f[I.emails] || '',
      link: f[I.link] || '',
      review_rating: f[I.rating] || '',
      review_count: f[I.resenas] || '',
    },
  }));

// Resumen de la corrida, para ver de un vistazo si sirvió.
const tandas = $input.all().map((i) => i.json);
const suma = (campo) => tandas.reduce((t, x) => t + (Number(x[campo]) || 0), 0);

return [{
  json: {
    cuenta: $('Perfil y búsquedas de la semana').first().json.cuenta,
    busquedas: $('Perfil y búsquedas de la semana').first().json.tanda,
    recibidos: suma('recibidos'),
    nuevos: suma('nuevos'),
    repetidos: suma('repetidos'),
    cuando: $now.toFormat('yyyy-LL-dd HH:mm'),
  },
}];
